//     · s136 点名蒙眼带/皮手铐/震动棒/鞭/项圈/袜子 ⇒ 蒙眼 10、绑 22、震动棒 22、鞭 13、项圈 24、袜 5 ✓
//     · s136 **没点名长靴** ⇒ 长靴 0；s138 **没点名手套** ⇒ 手套 0；
//       s139 **没点名项圈/手套/袜子** ⇒ 三个全是 0 ✓
//     · s118 起因里**漏了震动棒**（大纲第 8 步写了）⇒ 震动棒 **0** ✗
//     ⇒ 检查清单第一条：**把大纲里所有道具名，在起因里再念一遍** ✓
//  7. **「鞭子真响」这件事，写大纲管不住** —— 五场里「鞭」共 70 次、「啪」只有 7 次：
