//     ⇒ 这不是「没点名」能解决的，别再靠改大纲试了（已经试过 5 次）✓
//  8. **大纲/起因里的括号，会被抄进正文**（读起来像剧本）：
//     s136 通篇 **83 处**括注（「（我把袜子拎起来，抖了一下）」「（停在那儿，没动）」）；
//     而写法几乎一样的 s137 是 **0 处** ⇒ 不稳定，**每场跑完都要盯一眼「括号」那一列** ✓
//  9. **12 步 × 每步 4 轮 = 48 轮**，正好铺满 45 轮不回绕（原来 10 步 × 4 = 40，
//     第 41 轮就绕回第 1 步，可那时人早到过顶了）⇒ **跑 45 轮就写 12 步** ✓
//
