//
//  10. **"多说话"的要求会诱发剧本腔** —— 加了「S 每轮都要有一句嘲她的话」之后，
//      s118 整场变成「（靴尖退出来一点）舌头出来」这种**括号 + 台词**的舞台指示（一次 397 处）。
//      ⇒ 想提高台词密度，**必须同时钉死格式**（adult-scene.md 的 ⑬-b：动作写进句子里，
//        不许写成"（动作）台词"）✓ 只加密度不加格式禁令 = 一定崩成剧本 ✗
